import * as THREE from './vendor/three.module.js';
const maps={};
export async function loadSurfaces(quality="high"){const loader=new THREE.TextureLoader();await Promise.all(['red_dirt_mud_01','plastered_wall_02','corrugated_iron_02','wood_planks'].map(async name=>{maps[name]={};await Promise.all((quality==='low'?['color']:['color','normal','roughness']).map(async kind=>{const tex=await loader.loadAsync(`assets/${quality==='low'?'mobile/':''}textures/${name}_${kind}.jpg`);tex.wrapS=tex.wrapT=THREE.RepeatWrapping;tex.anisotropy=8;if(kind==='color')tex.colorSpace=THREE.SRGBColorSpace;tex.userData.sharedAsset=true;maps[name][kind]=tex;}));}));}
export function surface(name,color=0xffffff,repeatX=1,repeatY=repeatX){const source=maps[name];if(!source)return new THREE.MeshStandardMaterial({color,roughness:.9});const options={color,roughness:.95,metalness:name.startsWith('corrugated')?.28:0,normalScale:new THREE.Vector2(name==='red_dirt_mud_01'?.3:.7,name==='red_dirt_mud_01'?.3:.7)};for(const [kind,tex]of Object.entries(source)){const copy=tex.clone();copy.repeat.set(repeatX,repeatY);copy.userData.sharedAsset=false;options[{color:'map',normal:'normalMap',roughness:'roughnessMap'}[kind]]=copy;}return new THREE.MeshStandardMaterial(options);}
export function weatherMesh(mesh,name,color,rx=1,ry=rx){mesh.material.dispose();mesh.material=surface(name,color,rx,ry);return mesh;}
